message.content:
{
  "html": "<section data-ui-unit="booking">
  <div class="booking-host">
    <h3 class="booking-host-title">틈 도자기 스튜디오</h3>
    <p class="booking-host-subtitle">재료와 도구 포함 · 완성품 소성 후 수령</p>
  </div>
  <div class="booking-action-row">
    <button id="favorite" class="booking-icon-btn" type="button" aria-label="수업 찜하기" aria-pressed="false">
      <img src="assets/icons/Heart.svg" alt="" width="24" height="24">
    </button>
    <button id="book" class="booking-primary-btn" type="button">일정 선택하고 예약하기</button>
  </div>
  <p class="booking-note">일정을 선택한 뒤 예약 내용을 확인할 수 있어요.</p>
</section>",
  "css": "[data-ui-unit="booking"] {
  display: block;
  width: 100%;
}

.booking-host {
  border-top: 1px solid #ededf0;
  padding: 20px 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.booking-host-title {
  font-size: 16px;
  font-weight: 700;
  color: #202024;
  margin: 0;
  line-height: 1.3;
}

.booking-host-subtitle {
  font-size: 14px;
  color: #60606a;
  margin: 0;
  line-height: 1.4;
}

.booking-action-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 12px;
  padding-top: 20px;
}

@media (min-width: 600px) {
  .booking-action-row {
    grid-template-columns: auto minmax(0, 1fr);
    align-items: center;
  }
}

.booking-icon-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  border: none;
  background: transparent;
  padding: 0;
  cursor: pointer;
  transition: background-color 0.15s ease;
}

.booking-icon-btn img {
  width: 24px;
  height: 24px;
  display: block;
  pointer-events: none;
}

.booking-icon-btn:hover {
  background-color: #f4f4f6;
}

.booking-icon-btn:focus-visible {
  outline: 3px solid #5146d7;
  outline-offset: 2px;
}

.booking-icon-btn[aria-pressed="true"] img {
  filter: invert(27%) sepia(98%) saturate(1000%) hue-rotate(270deg) brightness(1.1) contrast(1.1);
}

.booking-primary-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 52px;
  background-color: #5146d7;
  color: #ffffff;
  font-size: 16px;
  font-weight: 700;
  border-radius: 6px;
  border: none;
  cursor: pointer;
  transition: background-color 0.15s ease, transform 0.1s ease;
}

.booking-primary-btn:hover {
  background-color: #4338c2;
}

.booking-primary-btn:active {
  transform: scale(0.98);
  background-color: #3b31a6;
}

.booking-primary-btn:focus-visible {
  outline: 3px solid #5146d7;
  outline-offset: 2px;
}

.booking-note {
  font-size: 14px;
  color: #60606a;
  line-height: 1.6;
  margin-top: 12px;
  margin-bottom: 0;
}"
}
